#include <stdexcept>
#include "bridge.hpp"
#include "config.hpp"
#include "files.hpp"
#include "format.hpp"
#include "keywords.hpp"
#include "options.hpp"

namespace blitz::lsp::bridge {
	bool is_keyword(std::string_view word)
	{
		return !tools::keyword_spelling(word).empty();
	}

	std::string read_file(std::filesystem::path const& file)
	{
		return tools::read_file(file);
	}

	std::vector<std::filesystem::path> find_sources(std::filesystem::path const& folder)
	{
		try {
			return tools::find_sources(folder);
		} catch (std::exception const&) {
			return {};
		}
	}

	std::string format_text(std::string const& source, std::filesystem::path const& file, bool use_tabs, int tab_width, bool editor_indentation)
	{
		blitz::format::options options;
		if (editor_indentation) {
			options.indent_with_tabs = use_tabs;
			if (tab_width > 0) options.indent_width = tab_width;
		}
		auto dir = file.has_parent_path() ? file.parent_path() : std::filesystem::path(".");
		if (auto config = tools::find_config(dir, { ".blitz-format", "blitz-format.json" })) {
			for (auto const& [key, value] : tools::load_config(*config)) {
				std::string error;
				if (!blitz::format::set_option(options, key, value, error)) throw std::runtime_error(error);
			}
		}
		return blitz::format::format_source(source, options);
	}
} // namespace blitz::lsp::bridge
